// v10.1.1: the Home button's flag layer, drawn from the bundled
// sprite (assets/flags_sprite.png) — real flag artwork, offline,
// for every country code, not just the tested ones. The sprite
// index lives in flag_sprite_data.dart (generated by
// ~/workspace/gen_flag_sprite.py).
import 'dart:math' as math;
import 'dart:ui' as ui;

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';

import 'flag_sprite_data.dart';

// One shared future: FutureBuilder must keep the same instance
// across rebuilds (the wash animation ticks ~14 frames), or the
// flag would flicker back to empty on every tick.
Future<ui.Image>? _spriteFuture;
Future<ui.Image> _loadSprite() {
  final f = _spriteFuture;
  if (f != null) return f;
  final created = () async {
    final data = await rootBundle.load('assets/flags_sprite.png');
    final codec = await ui.instantiateImageCodec(data.buffer.asUint8List());
    final frame = await codec.getNextFrame();
    return frame.image;
  }();
  _spriteFuture = created;
  return created;
}

/// One country's flag from the sprite, drawn to cover a square
/// (the button circle) like CSS object-fit: cover — centered,
/// except hoist-band flags (UAE) which align left so the band
/// shows as a crescent at the circle's edge. Unknown codes fall
/// back to their 2 letters, so the button still works for any
/// country, even one missing from the sprite.
class FlagSprite extends StatelessWidget {
  const FlagSprite({super.key, required this.code});
  final String code;

  @override
  Widget build(BuildContext context) {
    final info = flagSpriteIndex[code];
    if (info == null) {
      return Center(
        child: Text(code.toUpperCase(),
            style: const TextStyle(
                color: Colors.white,
                fontWeight: FontWeight.w800,
                fontSize: 28,
                letterSpacing: 2)),
      );
    }
    return FutureBuilder<ui.Image>(
      future: _loadSprite(),
      builder: (_, snap) {
        final img = snap.data;
        if (img == null) return const SizedBox.shrink();
        return CustomPaint(painter: _FlagPainter(img, info, flagSpriteLeftAligned.contains(code)));
      },
    );
  }
}

class _FlagPainter extends CustomPainter {
  _FlagPainter(this.image, this.info, this.leftAlign);
  final ui.Image image;
  final ({int index, double aspect}) info;
  final bool leftAlign;

  @override
  void paint(Canvas canvas, Size size) {
    const cell = flagSpriteCell;
    final col = info.index % flagSpriteCols;
    final row = info.index ~/ flagSpriteCols;
    // The flag was fitted INSIDE its cell: wide flags span the
    // full cell width, tall ones (Iran) the full cell height.
    final w = info.aspect >= 1 ? cell : cell * info.aspect;
    final h = info.aspect >= 1 ? cell / info.aspect : cell;
    final src = Rect.fromLTWH(
        col * cell + (cell - w) / 2, row * cell + (cell - h) / 2, w, h);
    final scale = math.max(size.width / w, size.height / h);
    final dw = w * scale;
    final dh = h * scale;
    final dx = leftAlign ? 0.0 : (size.width - dw) / 2;
    final dy = (size.height - dh) / 2;
    canvas.drawImageRect(image, src, Rect.fromLTWH(dx, dy, dw, dh), Paint());
  }

  @override
  bool shouldRepaint(covariant _FlagPainter o) =>
      o.image != image || o.info != info || o.leftAlign != leftAlign;
}

/// Left-to-right reveal clip for the wash: 0 = green button only,
/// 1 = flag fully shown (and it stays shown).
class RevealClipper extends CustomClipper<Rect> {
  RevealClipper(this.value);
  final double value;
  @override
  Rect getClip(Size size) => Rect.fromLTWH(0, 0, size.width * value, size.height);
  @override
  bool shouldReclip(covariant RevealClipper o) => o.value != value;
}
